SELECT

FROM erp_business_metric
WHERE deleted = 0

    AND tenant_id = #{query.tenantId}


    AND metric_code = #{query.metricCode}


    AND metric_type = #{query.metricType}


    AND metric_type IN

        #{type}



    AND period = #{query.period}


    AND stat_time >= #{query.startTime}


    AND stat_time <= #{query.endTime}

ORDER BY stat_time DESC

SELECT

FROM erp_business_metric
WHERE tenant_id = #{tenantId}
AND metric_code = #{metricCode}
AND period = #{period}
AND stat_time >= #{startTime}
AND stat_time <= #{endTime}
AND deleted = 0
ORDER BY stat_time

SELECT

FROM erp_business_metric
WHERE tenant_id = #{tenantId}
AND metric_code = #{metricCode}
AND period = #{period}
AND stat_time >= DATE_SUB(NOW(), INTERVAL #{hours} HOUR)
AND deleted = 0
ORDER BY stat_time
